#!/usr/bin/env python3
"""Generate a portable static portfolio with the Python standard library.

Usage: python3 scripts/build.py [--origin https://your-project.pages.dev]
The root CNAME is deliberately never touched or copied to dist.
"""
from pathlib import Path
from html import escape as esc
from urllib.parse import quote, urlparse
import argparse, json, shutil, os

ROOT = Path(__file__).resolve().parents[1]
SITE = json.loads((ROOT / 'content/site.json').read_text())
MEDIA = json.loads((ROOT / 'content/media.json').read_text())
parser = argparse.ArgumentParser()
parser.add_argument('--origin', default=os.environ.get('SITE_URL', 'https://khaled-hasan-hasan.github.io'))
args = parser.parse_args()
u = urlparse(args.origin)
if u.scheme != 'https' or not u.netloc or u.path not in ('', '/') or u.query or u.fragment or u.username:
    parser.error('--origin must be an HTTPS origin without a path, query or credentials')
ORIGIN = args.origin.rstrip('/')
ARROW = '<span aria-hidden="true">↗</span>'
NEXT = '<span aria-hidden="true">→</span>'
PAGES = {}

def mail(service='Data analytics project'):
    return 'mailto:' + SITE['email'] + '?subject=' + quote('Project inquiry — ' + service) + '&body=' + quote('Hi Khaled,\n\nI would like to discuss ' + service.lower() + '.\n\nBusiness question:\nData sources:\nExpected deliverables:\nTarget date (if any):\n\nThanks,')

def link(url, text, cls='text-link', external=False):
    return f'<a class="{cls}" href="{esc(url, quote=True)}"' + (' target="_blank" rel="noopener noreferrer"' if external else '') + f'>{text}</a>'

def image(name, alt, prefix='', lazy=True, small=False):
    m = MEDIA[name]
    sizes = 'sizes="(max-width: 700px) 92vw, 50vw"'
    srcset = f' srcset="{prefix}assets/images/{name}-small.webp 720w, {prefix}assets/images/{name}.webp {m["width"]}w" {sizes}' if small and m['width'] > 720 else ''
    return f'<img src="{prefix}assets/images/{name}.webp"{srcset} width="{m["width"]}" height="{m["height"]}" alt="{esc(alt, quote=True)}" ' + ('loading="lazy" decoding="async"' if lazy else 'fetchpriority="high"') + '>'

def tags(items):
    return '<ul class="tags" aria-label="Technologies">' + ''.join('<li>' + esc(i) + '</li>' for i in items) + '</ul>'

def eyebrow(n, text):
    return f'<p class="eyebrow"><span>{n}</span> {text}</p>'

def cta(prefix='', title='Have a question your data should answer?'):
    return f'''<section class="closing"><div class="wrap closing-inner"><div><p class="eyebrow">LET’S MAKE IT CLEARER</p><h2>{title}</h2><p>Tell me what you’re working with, and what you need to understand.</p></div>{link(prefix+'contact.html', 'Discuss Your Project '+ARROW, 'button button-lime')}</div></section>'''

def page(path, title, desc, body, active='', schema=None):
    prefix = '../' if '/' in path else ''
    nav = [('work.html','Work','work'),('services.html','Services','services'),('about.html','About','about')]
    navhtml=''.join(f'<a href="{prefix+p}"'+(' aria-current="page"' if key == active else '')+f'>{text}</a>' for p,text,key in nav)
    canonical=ORIGIN + ('/' if path == 'index.html' else '/'+path)
    data = schema or {'@context':'https://schema.org','@type':'WebPage','name':title,'description':desc,'url':canonical,'inLanguage':'en'}
    if path == 'index.html':
        data = {'@context':'https://schema.org','@type':'Person','name':SITE['name'],'url':ORIGIN+'/', 'jobTitle':'Data Analyst and BI Developer','email':'mailto:'+SITE['email'],'sameAs':[SITE['github'],SITE['linkedin']]}
    html=f'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="description" content="{esc(desc, quote=True)}">
<meta name="theme-color" content="#173c32">
<title>{esc(title)} | SmartDataVisions</title>
<link rel="canonical" href="{canonical}">
<meta property="og:type" content="website">
<meta property="og:site_name" content="SmartDataVisions — Khaled Hasan">
<meta property="og:title" content="{esc(title, quote=True)}">
<meta property="og:description" content="{esc(desc, quote=True)}">
<meta property="og:url" content="{canonical}">
<meta property="og:image" content="{ORIGIN}/assets/social-preview.png">
<meta property="og:image:width" content="1200"><meta property="og:image:height" content="630">
<meta property="og:image:alt" content="SmartDataVisions — Clear data. Better decisions. Independent analytics by Khaled Hasan.">
<meta name="twitter:card" content="summary_large_image">
<link rel="icon" type="image/svg+xml" href="{prefix}assets/favicon.svg">
<link rel="preload" href="{prefix}assets/fonts/manrope-latin.woff2" as="font" type="font/woff2" crossorigin>
<link rel="stylesheet" href="{prefix}style.css">
<script type="application/ld+json">{json.dumps(data,ensure_ascii=False).replace('<','&lt;')}</script>
<script defer src="{prefix}script.js"></script>
</head>
<body>
<a class="skip-link" href="#main">Skip to content</a>
<header class="site-header"><div class="wrap header-inner">
<a class="brand" href="{prefix}index.html"><span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i><i></i></span><span>SmartData<span class="brand-light">Visions</span><small>BY KHALED HASAN</small></span></a>
<button class="menu-toggle" type="button" aria-expanded="false" aria-controls="navigation" hidden>Menu <span aria-hidden="true">+</span></button>
<nav id="navigation" class="navigation" aria-label="Main navigation">{navhtml}<a class="nav-contact" href="{prefix}contact.html"{(' aria-current="page"' if active=='contact' else '')}>Discuss Your Project {ARROW}</a></nav>
</div></header>
<main id="main" tabindex="-1">{body}</main>
<footer class="site-footer"><div class="wrap footer-top"><a class="footer-wordmark" href="{prefix}index.html">SmartDataVisions<span>Independent thinking. Clearer data.</span></a><div class="footer-links">{link(SITE['github'],'GitHub '+ARROW,external=True)}{link(SITE['linkedin'],'LinkedIn '+ARROW,external=True)}{link('mailto:'+SITE['email'],'Email '+ARROW)}</div></div><div class="wrap footer-bottom"><p>© 2026 Khaled Hasan · Cairo, Egypt</p><div>{link(prefix+'work.html','Selected work')}{link(prefix+'privacy.html','Privacy')}</div><a href="#main">Back to top ↑</a></div></footer>
</body></html>'''
    PAGES[path]=html

def project_card(p, prefix='', featured=False):
    return f'''<article class="work-card {p['color']}" data-category="{p['category']}"><a class="work-visual" href="{prefix}case-studies/{p['id']}.html"><div class="visual-top"><span>{p['categoryLabel']}</span><span aria-hidden="true">↗</span></div>{image(p['image'],p['gallery'][0][1],prefix,small=True)}<span class="visual-caption">ORIGINAL PROJECT ARTIFACT</span></a><div class="work-caption"><p class="eyebrow">{esc(p['label'])}</p><h3>{link(prefix+'case-studies/'+p['id']+'.html',esc(p['title']),'title-link')}</h3><p>{esc(p['summary'])}</p>{link(prefix+'case-studies/'+p['id']+'.html','Read the case study '+NEXT)}</div></article>'''

home=f'''<section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><p class="eyebrow"><span class="status-dot" aria-hidden="true"></span> INDEPENDENT DATA ANALYTICS CONSULTANT</p><h1>Better decisions<br>start with<br><span class="serif">clearer data.</span></h1><p class="hero-intro">I’m Khaled Hasan. I turn scattered spreadsheets and complex data into clear dashboards, reliable reports and repeatable workflows.</p><div class="actions">{link('contact.html','Discuss Your Project '+ARROW,'button button-dark')}{link('work.html','Explore My Work '+NEXT,'button button-plain')}</div><p class="hero-footnote">Power BI dashboards · Data preparation · Reporting automation</p></div><div class="hero-art"><div class="report-frame"><div class="report-top"><span class="tiny-squares" aria-hidden="true">▥</span><span>FROM THE PORTFOLIO</span><span class="report-index">01 / 05</span></div><a href="case-studies/hotel-booking.html" class="hero-report" aria-label="Explore the Hotel Booking Analysis Dashboard">{image('hotel-overview','Original Hotel Booking Analysis Power BI report, showing booking indicators and charts.',lazy=False,small=True)}</a><div class="report-caption"><div><span class="eyebrow">POWER BI / HOSPITALITY</span><p>See the bigger picture.</p></div><a class="round-link" href="case-studies/hotel-booking.html" aria-label="Read Hotel Booking Analysis Dashboard case study">{ARROW}</a></div></div><div class="pipeline-note"><span class="note-mark" aria-hidden="true">↳</span><div><strong>From raw data to a useful answer.</strong><p>Clean <span>→</span> Model <span>→</span> Visualize</p></div></div><p class="art-note">REAL PROJECTS. INSPECTABLE WORK.</p></div></div></section>
<section class="tools-strip" aria-label="Core tools"><div class="wrap tools-inner"><p>A practical toolkit.<br><strong>A connected approach.</strong></p><ul><li><span class="tool-icon bars" aria-hidden="true">▥</span>Power BI</li><li><span class="tool-icon" aria-hidden="true">▦</span>Excel</li><li><span class="tool-icon" aria-hidden="true">⌘</span>SQL Server</li><li><span class="tool-icon" aria-hidden="true">⌁</span>Python</li><li>PostgreSQL</li></ul></div></section>
<section class="section wrap" id="selected-work"><div class="section-heading"><div>{eyebrow('01','SELECTED WORK')}<h2>The thinking.<br><span class="serif">And the evidence.</span></h2></div><div><p>A closer look at how I structure data, build reports and approach analytical problems.</p>{link('work.html','Explore all five projects '+NEXT)}</div></div><div class="work-grid">{project_card(SITE['projects'][0])}{project_card(SITE['projects'][1])}</div><div class="other-work"><p class="eyebrow">ALSO IN THE PORTFOLIO</p>'''+''.join(f'''<a href="case-studies/{p['id']}.html"><span>{p['categoryLabel']}</span><strong>{p['title']}</strong><span aria-hidden="true">↗</span></a>''' for p in SITE['projects'][2:])+'''</div></section>
<section class="services-home section"><div class="wrap"><div class="section-heading"><div>'''+eyebrow('02','HOW I CAN HELP')+'''<h2>Less friction.<br><span class="serif">More understanding.</span></h2></div><div><p>Whether you need a single dashboard or a better reporting process, start with the problem you want to solve.</p>'''+link('services.html','Find the right service '+NEXT)+'''</div></div><div class="service-list">'''+''.join(f'''<a class="service-row" href="services.html#{s['id']}"><span class="service-number">0{i+1}</span><h3>{esc(s['title'])}</h3><p>{esc(s['short'])}</p><span class="service-arrow" aria-hidden="true">↗</span></a>''' for i,s in enumerate(SITE['services']))+'''</div></div></section>
<section class="section wrap approach"><div>'''+eyebrow('03','A CLEAR WAY OF WORKING')+'''<h2>Start with the question.<br><span class="serif">Build the right answer.</span></h2><p class="large-copy">Good analytics starts before the first chart. I focus on the decisions behind the report, the quality of the inputs, and what happens after handover.</p>'''+link('about.html','Meet the person behind the work '+NEXT)+'''</div><ol class="process-list"><li><span>01</span><div><h3>Understand</h3><p>Clarify the business question, audience, data sources and definition of done.</p></div></li><li><span>02</span><div><h3>Build & validate</h3><p>Prepare the data, develop the solution and check the result against agreed rules.</p></div></li><li><span>03</span><div><h3>Explain & hand over</h3><p>Walk through the output, document the assumptions and make the next steps clear.</p></div></li></ol></section>'''+cta()
page('index.html','Data analytics for clearer business decisions','Independent data analytics by Khaled Hasan. Power BI dashboards, Excel automation, SQL reporting and Python data processing, with inspectable project work.',home)

services=f'''<section class="page-hero wrap">{eyebrow('SERVICES','BUILT AROUND YOUR QUESTION')}<h1>Your data challenge.<br><span class="serif">A focused solution.</span></h1><p class="page-lead">Dashboards that explain. Data you can work with. Reporting you can repeat. I scope each project around the decision you need to make.</p></section><div class="wrap service-jump" aria-label="Service index">'''+''.join(link('#'+s['id'],s['title'],'chip') for s in SITE['services'])+'''</div><section class="wrap service-details" aria-label="Service details">'''
for i,s in enumerate(SITE['services']):
    proof=link('case-studies/'+s['project']+'.html','Explore related project work '+NEXT) if s.get('project') else '<p class="muted small">Scope and acceptance checks are agreed around your data.</p>'
    services+=f'''<article class="service-detail" id="{s['id']}"><div class="service-detail-title"><span class="big-number">0{i+1}</span><h2>{s['title']}</h2><p>{s['short']}</p><p class="tool-line">{s['tools']}</p>{link(mail(s['title']),'Discuss this service '+ARROW,'button button-dark')}</div><div><h3>The problem</h3><p>{s['problem']}</p><h3>How I help</h3><p>{s['solution']}</p><h3>What you receive</h3><ul class="check-list">{''.join('<li>'+d+'</li>' for d in s['deliverables'])}</ul><h3>Typical scope</h3><p>{s['scope']}</p>{proof}</div></article>'''
services+='''</section><section class="section faq-band"><div class="wrap faq-grid"><div><p class="eyebrow">BEFORE WE START</p><h2>A few practical<br><span class="serif">questions.</span></h2></div><div><details><summary>What should I share in an inquiry?</summary><p>The business question, data sources, expected deliverable and any target date. Start with a description or a redacted sample; we can agree how to handle sensitive data before you share it.</p></details><details><summary>How do you estimate the scope and cost?</summary><p>After reviewing the inputs, complexity, access requirements and acceptance criteria. There is no fixed price or delivery promise before we define the work together.</p></details><details><summary>Can we start with an existing report?</summary><p>Yes. Describe what is difficult to use or maintain, and what you want it to do. An initial review can help define whether the work is a focused improvement or a wider rebuild.</p></details><details><summary>What about data engineering or machine learning?</summary><p>My portfolio includes database, ETL and machine-learning studies. If your project needs these capabilities, we can review the requirements and decide whether they fit the problem and scope.</p></details></div></div></section>'''+cta()
page('services.html','Data analytics services','Power BI dashboards, Excel cleaning, SQL analysis, SKU reconciliation, reporting automation and Python processing. Explore deliverables and discuss your scope.',services,'services')

work=f'''<section class="page-hero wrap">{eyebrow('THE PORTFOLIO','METHODS YOU CAN INSPECT')}<h1>From the question<br><span class="serif">to the work.</span></h1><p class="page-lead">Five projects across business intelligence, SQL and Python. Each case study separates what was built, what the evidence shows, and what still needs verification.</p><p class="context-note">Portfolio and training projects. No client relationships or commercial outcomes are implied.</p></section><section class="wrap section work-index"><div class="work-toolbar"><p><strong id="project-count">5</strong> projects</p><div class="filters" aria-label="Filter projects" hidden><button type="button" data-filter="all" aria-pressed="true">All work</button><button type="button" data-filter="bi" aria-pressed="false">Business intelligence</button><button type="button" data-filter="sql" aria-pressed="false">SQL</button><button type="button" data-filter="python" aria-pressed="false">Python & ML</button></div></div><p id="filter-status" class="sr-only" role="status"></p><div class="work-grid" id="project-grid">'''+''.join(project_card(p) for p in SITE['projects'])+'''</div></section>'''+cta(title='Working on a similar problem?')
page('work.html','Selected data analytics projects','Explore five evidence-based portfolio case studies: Power BI, examination data, PostgreSQL analytics, marketing analysis and fraud detection.',work,'work')

for p in SITE['projects']:
    prefix='../'
    sources=''.join(link(url,esc(label)+' '+ARROW,'button button-outline',external=True) for label,url in p['links'])
    if not sources:sources='<p>The former public code link is unavailable. Explore the retained project artifacts below.</p>'
    gallery=''.join(f'''<figure>{link('../assets/images/'+name+'.webp',image(name,caption,'../'),'image-link')}<figcaption>{esc(caption)} <span>Open image to inspect.</span></figcaption></figure>''' for name,caption in p['gallery'])
    video=''
    if p.get('video'):
        video='''<figure class="video-figure"><video controls preload="none" width="1280" height="720" poster="../assets/images/hotel-overview.webp" aria-label="Hotel booking dashboard navigation recording, silent version"><source src="../assets/hotel-walkthrough.mp4" type="video/mp4"><p>Your browser cannot play the recording. <a href="../assets/hotel-walkthrough.mp4">Download the recording</a>.</p></video><figcaption>Original dashboard walkthrough, compressed with audio removed. The pointer explores charts, filters and report pages. For the same information as static images, see the three report views above. Figures vary with the selected filters.</figcaption></figure>'''
    body=f'''<section class="case-hero wrap"><a class="back-link" href="../work.html">← All work</a><p class="eyebrow">{p['label']}</p><h1>{p['title']}</h1><p class="page-lead">{p['summary']}</p>{tags(p['tools'])}<div class="case-hero-image {p['color']}">{image(p['image'],p['gallery'][0][1],'../',lazy=False,small=True)}</div><p class="context-note">Portfolio / training project · Original project artifacts · {p['categoryLabel']}</p></section><div class="wrap case-layout"><nav class="case-toc" aria-label="Case study sections"><p class="eyebrow">IN THIS CASE STUDY</p><a href="#challenge">The challenge</a><a href="#context">Dataset & objectives</a><a href="#approach">Approach & architecture</a><a href="#visual-results">Visual results</a><a href="#outcomes">Verified outcomes</a><a href="#sources">Source material</a></nav><div class="case-content"><section id="challenge"><p class="eyebrow">01 / BUSINESS CHALLENGE</p><h2>The question behind the work.</h2><p>{p['challenge']}</p></section><section id="context"><p class="eyebrow">02 / DATASET & OBJECTIVES</p><h2>Start with the context.</h2><p>{p['context']}</p><h3>Project objectives</h3><ul class="check-list">{''.join('<li>'+o+'</li>' for o in p['objectives'])}</ul></section><section id="approach"><p class="eyebrow">03 / TECHNICAL APPROACH</p><h2>How the pieces connect.</h2><p>{p['approach']}</p><div class="architecture-panel"><p class="eyebrow">ARCHITECTURE / DATA MODEL</p><p>{p['architecture']}</p></div><h3>Implementation</h3><p>{p['implementation']}</p></section><section id="outcomes"><p class="eyebrow">04 / VERIFIED OUTCOMES</p><h2>What the work demonstrates.</h2><p>{p['outcome']}</p><aside class="evidence-note"><h3>Evidence & limitations</h3><p>{p['evidence']}</p></aside></section><section id="sources"><p class="eyebrow">05 / SOURCE MATERIAL</p><h2>Look closer.</h2><div class="source-links">{sources}</div><h3>Technologies</h3>{tags(p['tools'])}</section></div></div><section class="section wrap case-gallery" id="visual-results"><div class="section-heading"><div><p class="eyebrow">06 / VISUAL RESULTS</p><h2>The original artifacts.</h2></div><p>Genuine project visuals, retained from the original portfolio. Open any image to inspect it in full.</p></div><div class="gallery-grid">{gallery}</div>{video}</section><section class="wrap related-service"><p>Have a similar reporting or data challenge?</p>{link('../services.html#'+p['relatedService'],'Explore the related service '+NEXT)}</section>'''+cta('../',title='Let’s make your data useful.')
    page('case-studies/'+p['id']+'.html',p['title'],p['summary'],body,'work')

credentials=[('MSc in Data Science','Cairo University','Previously listed as in progress, expected 2026. Current enrollment or completion needs confirmation.'),('BSc in Computer Science','Tanta University · 2023','Self-reported in the original portfolio; degree verification not linked.'),('Power BI Developer Track','Information Technology Institute · 2025','Supported by the ITI project author description; completion certificate not linked.'),('Machine Learning Trainee','National Telecommunication Institute · 2024','Self-reported training; completion evidence not linked.'),('Associate Data Analyst in SQL','DataCamp · 2025','Status differs across published profiles; completion requires confirmation.'),('Google Data Analytics Professional Certificate','Coursera · 2024','Self-reported; public credential URL not supplied.'),('Data Analyst with Python Track','DataCamp · 2022','Self-reported; public completion URL not supplied.'),('Data Challenger Track','FWD / Udacity · 2021','Self-reported; public completion URL not supplied.')]
about=f'''<section class="page-hero wrap about-hero">{eyebrow('ABOUT','THE PERSON BEHIND THE WORK')}<h1>Technical curiosity.<br><span class="serif">Practical thinking.</span></h1><div class="about-intro"><div class="monogram" aria-label="Khaled Hasan initials">kh<span>DATA / CLARITY / CRAFT</span></div><div><h2>I’m Khaled Hasan.</h2><p class="large-copy">An independent data analyst and BI developer based in Cairo, Egypt, with a portfolio spanning dashboards, databases, analytical workflows and machine-learning studies.</p><p>I enjoy connecting the details: how a source file becomes a usable table, how a measure answers a real question, and how a report helps someone understand what to do next.</p><p>For freelance work, my focus is Power BI, Excel, SQL, data reconciliation and Python processing. Data engineering and machine learning support that foundation when the problem calls for them.</p>{link(SITE['github'],'Inspect my public work '+ARROW,external=True)}</div></div></section><section class="section about-values"><div class="wrap"><p class="eyebrow">WHAT I BRING TO THE WORK</p><div class="value-grid"><div><span>01 / CONNECTED THINKING</span><h2>Beyond the chart.</h2><p>My examination project connects application records, database design and reporting. I consider how the pieces fit together.</p></div><div><span>02 / READABLE OUTPUT</span><h2>Clarity in the handover.</h2><p>Definitions, assumptions and operating notes are part of the proposed deliverable, so the result can be understood after the project.</p></div><div><span>03 / HONEST EVIDENCE</span><h2>Show the work.</h2><p>My case studies link the available artifacts and explain their limits. A portfolio result is presented as a portfolio result.</p></div></div></div></section><section class="section wrap credentials"><div><p class="eyebrow">BACKGROUND & LEARNING</p><h2>A foundation<br><span class="serif">in data.</span></h2><p>Education and training retained from my original portfolio.</p><p class="context-note">These entries are self-reported. Public verification links have not been supplied; current status is flagged below.</p></div><div class="credential-list">'''+''.join(f'''<article><h3>{esc(title)}</h3><p class="credential-org">{esc(org)}</p><p>{esc(note)}</p></article>''' for title,org,note in credentials)+'''</div></section>'''+cta()
page('about.html','About Khaled Hasan','Meet Khaled Hasan, an independent data analyst and BI developer in Cairo. Explore his technical approach, project background and self-reported education.',about,'about')

service_options = '<option value="Data analytics project">Help choosing a service</option>' + ''.join('<option value="'+esc(s["title"], quote=True)+'">'+esc(s["title"])+'</option>' for s in SITE["services"])
contact=f'''<section class="page-hero wrap contact-hero">{eyebrow('LET’S TALK','START WITH YOUR QUESTION')}<h1>What would you like<br><span class="serif">your data to tell you?</span></h1><p class="page-lead">A dashboard to build, a report to simplify, or two files that refuse to agree. Tell me what you’re working on.</p></section><section class="wrap contact-layout"><div class="contact-primary"><p class="eyebrow">THE MOST DIRECT ROUTE</p><h2>Tell me about your project.</h2>{link(mail(),'Email Khaled '+ARROW,'button button-dark')}<a class="email-address" href="mailto:{SITE['email']}">{SITE['email']}</a><button class="copy-email text-link" type="button" data-email="{SITE['email']}" hidden>Copy email address</button><p id="copy-status" class="small" role="status"></p><p class="small muted">Opens your email app. You can also copy the address into your preferred mail service.</p><div class="contact-social"><p>Prefer a professional profile?</p>{link(SITE['linkedin'],'Connect on LinkedIn '+ARROW,external=True)}{link(SITE['github'],'Explore GitHub '+ARROW,external=True)}</div></div><div class="inquiry-guide"><p class="eyebrow">A USEFUL STARTING POINT</p><h2>A little context goes a long way.</h2><ol><li><strong>The question</strong><p>What decision or business process should this help with?</p></li><li><strong>The data</strong><p>Where does it live, and what formats are you working with?</p></li><li><strong>The result</strong><p>What would a useful deliverable look like? Include any target date or budget range you want me to consider.</p></li></ol><p class="small muted">A description is enough to start. We can agree on access and how to handle sensitive information before sharing files.</p></div></section><section class="wrap composer-section" id="email-composer" hidden><div><p class="eyebrow">OPTIONAL / MAKE A START</p><h2>Shape your inquiry.</h2><p>This prepares a draft in your email app. Your entries stay in this page until you choose to open the draft; this website does not submit or save them.</p></div><form id="inquiry-form"><div class="form-row"><div><label for="service">What do you need?</label><select id="service" name="service">{service_options}</select></div><div><label for="timeline">Target date <span>(optional)</span></label><input id="timeline" name="timeline" type="text" maxlength="120" placeholder="A date, or still exploring"></div></div><label for="brief">Your question, data and expected result</label><textarea id="brief" name="brief" rows="5" required minlength="15" maxlength="5000" placeholder="I have monthly exports from… and need to understand…"></textarea><button class="button button-dark" type="submit">Prepare email draft <span aria-hidden="true">↗</span></button><p id="draft-status" role="status" class="small"></p><a id="email-draft" class="button button-outline" hidden>Open email draft <span aria-hidden="true">↗</span></a></form></section><section class="wrap contact-note"><p><strong>Coming from a freelance platform?</strong> You can use the same project brief in Upwork, Contra, Fiverr or LinkedIn. Continue the conversation through the platform where we connected when its terms require it.</p></section>'''
page('contact.html','Discuss your data analytics project','Contact Khaled Hasan about Power BI, Excel, SQL, data matching and Python projects. Direct Gmail and LinkedIn links with an optional local email draft builder.',contact,'contact')

page('privacy.html','Privacy','How this static portfolio handles your visit and optional project inquiry draft.',f'''<section class="page-hero wrap narrow"><p class="eyebrow">PRIVACY / 11 NOVEMBER 2026</p><h1>A simple approach<br><span class="serif">to privacy.</span></h1><h2>On this website</h2><p>The portfolio does not include analytics trackers, advertising cookies, account registration or a contact-submission backend. Fonts and project images are served with the site.</p><h2>Your inquiry draft</h2><p>The optional draft builder processes text in your browser. It does not save it to browser storage or send it to a website server. Choosing “Open email draft” passes it to your email application, where your email provider’s policies apply.</p><h2>External services</h2><p>GitHub, Kaggle and LinkedIn links take you to external services with their own privacy policies. The hosting provider may process ordinary connection and request logs to operate and secure the website.</p><h2>Contact</h2><p>For questions about this portfolio, {link('mailto:'+SITE['email'],'email Khaled Hasan')}.</p></section>''')
page('404.html','Page not found','This page is not available. Explore Khaled Hasan’s data analytics work or discuss a project.',f'''<section class="page-hero wrap not-found"><p class="eyebrow">404 / A MISSING CONNECTION</p><h1>Let’s find a<br><span class="serif">clearer path.</span></h1><p class="page-lead">That page isn’t available. Your next step is below.</p><div class="actions">{link('/index.html','Back to home '+NEXT,'button button-dark')}{link('/work.html','Explore the work','button button-outline')}</div></section>''')
# A 404 may be rendered at any nested URL; absolute assets/navigation remain valid.
PAGES['404.html']=PAGES['404.html'].replace('href="assets/', 'href="/assets/').replace('href="style.css"','href="/style.css"').replace('src="script.js"','src="/script.js"')
for name in ['index.html','work.html','services.html','about.html','contact.html','privacy.html']:
    PAGES['404.html']=PAGES['404.html'].replace('href="'+name+'"','href="/'+name+'"')
for path, html in PAGES.items():
    dest=ROOT/path;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(html+'\n')
# Only intended website assets are published. CNAME and research are excluded.
dist=ROOT/'dist'
if dist.exists():shutil.rmtree(dist)
dist.mkdir()
for path in PAGES:
    dest=dist/path;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(ROOT/path,dest)
for name in ['style.css','script.js','_headers']:
    if (ROOT/name).exists():shutil.copy2(ROOT/name,dist/name)
shutil.copytree(ROOT/'assets',dist/'assets')
urls=''.join('<url><loc>'+ORIGIN+('/' if p=='index.html' else '/'+p)+'</loc></url>' for p in PAGES if p!='404.html')
(dist/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+urls+'</urlset>\n')
(dist/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n')
print(f'Built {len(PAGES)} static pages in dist/ for {ORIGIN}. CNAME preserved.')
